const todayStr = () => {
  const d = new Date();
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(
    d.getDate()
  ).padStart(2, "0")}`;
};

const nowTimeStr = () => {
  const d = new Date();
  return d.toLocaleTimeString("ar-EG", { hour: "2-digit", minute: "2-digit" });
};

const arabicDate = (dateStr) => {
  const d = dateStr ? new Date(`${dateStr}T12:00:00`) : new Date();
  return d.toLocaleDateString("ar-EG", { weekday: "long", year: "numeric", month: "long", day: "numeric" });
};

function buildDaySnapshot(employees, departments, mealIds) {
  const deptName = (id) => departments.find((d) => d.id === id)?.name || "";
  const attendance = employees.map((e) => ({
    empId: e.id,
    empNo: e.empNo,
    name: e.name,
    deptId: e.deptId,
    deptName: deptName(e.deptId),
    status: e.status,
    checkInTime: e.checkInTime || null,
    checkOutTime: e.checkOutTime || null,
  }));
  const meals = mealIds
    .map((m) => {
      const emp = employees.find((e) => e.id === m.empId);
      if (!emp) return null;
      return { empId: m.empId, empNo: emp.empNo, name: emp.name, deptId: emp.deptId, deptName: deptName(emp.deptId), time: m.time };
    })
    .filter(Boolean);
  return { attendance, meals };
}

function pruneArchive(archive, retentionDays) {
  const dates = Object.keys(archive).sort();
  if (dates.length <= retentionDays) return archive;
  const toRemove = dates.slice(0, dates.length - retentionDays);
  const pruned = { ...archive };
  toRemove.forEach((d) => delete pruned[d]);
  return pruned;
}

function normalizeHeader(s) {
  return String(s ?? "")
    .replace(/\uFEFF/g, "")
    .trim()
    .replace(/\s+/g, " ");
}

function findField(row, aliases) {
  const normalizedAliases = aliases.map(normalizeHeader);
  for (const key of Object.keys(row)) {
    if (normalizedAliases.includes(normalizeHeader(key))) {
      const v = row[key];
      return v === undefined || v === null ? "" : v;
    }
  }
  return "";
}

