function buildEmployeeLookup(employees) {
  const barcodeMap = new Map();
  const empNoMap = new Map();
  employees.forEach((e) => {
    if (e.barcode) barcodeMap.set(String(e.barcode).trim().toLowerCase(), e);
    if (e.empNo) empNoMap.set(String(e.empNo).trim().toLowerCase(), e);
  });
  return { barcodeMap, empNoMap };
}

function findEmployeeByCode(lookup, code) {
  const target = String(code ?? "").trim().toLowerCase();
  if (!target) return null;
  return lookup.barcodeMap.get(target) || lookup.empNoMap.get(target) || null;
}

function useBeep() {
  const ctxRef = useRef(null);
  return useCallback((type = "success") => {
    try {
      const AC = window.AudioContext || window.webkitAudioContext;
      if (!AC) return;
      if (!ctxRef.current) ctxRef.current = new AC();
      const ctx = ctxRef.current;
      if (ctx.state === "suspended") ctx.resume();
      const playTone = (freq, start, duration) => {
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.type = "sine";
        osc.frequency.value = freq;
        gain.gain.setValueAtTime(0.0001, ctx.currentTime + start);
        gain.gain.exponentialRampToValueAtTime(0.22, ctx.currentTime + start + 0.008);
        gain.gain.exponentialRampToValueAtTime(0.0001, ctx.currentTime + start + duration);
        osc.connect(gain);
        gain.connect(ctx.destination);
        osc.start(ctx.currentTime + start);
        osc.stop(ctx.currentTime + start + duration + 0.02);
      };
      if (type === "success") {
        playTone(1046, 0, 0.09);
      } else {
        playTone(280, 0, 0.11);
        playTone(280, 0.14, 0.11);
      }
    } catch (err) {
      // audio unavailable or blocked by the browser — fail silently
    }
  }, []);
}

/**
 * Listens for keystrokes fired by USB/Bluetooth "keyboard-wedge" barcode
 * scanners anywhere on the page (not just inside a focused scan field).
 * Scanners send characters extremely fast followed by Enter; we detect that
 * burst pattern and route the captured code to onScan. Normal human typing
 * inside real text fields is left completely untouched.
 */
function useHardwareScanner(enabled, onScan) {
  const bufferRef = useRef("");
  const lastTimeRef = useRef(0);

  useEffect(() => {
    if (!enabled) return undefined;
    const SCAN_GAP_MS = 60;

    const handleKeyDown = (e) => {
      const target = e.target;
      const isOwnScannerField = target && target.dataset && target.dataset.scannerInput === "true";
      if (isOwnScannerField) return; // the field's own handler already manages this

      const isEditable =
        target &&
        (target.tagName === "INPUT" ||
          target.tagName === "TEXTAREA" ||
          target.tagName === "SELECT" ||
          target.isContentEditable);
      if (isEditable) return; // never hijack legitimate typing elsewhere

      if (e.repeat) return;

      const now = Date.now();
      const gap = now - lastTimeRef.current;
      lastTimeRef.current = now;

      if (e.key === "Enter") {
        const code = bufferRef.current;
        bufferRef.current = "";
        if (code.length >= 3) {
          e.preventDefault();
          onScan(code);
        }
        return;
      }

      if (e.ctrlKey || e.altKey || e.metaKey) return;
      if (e.key.length !== 1) return; // ignore Shift/Tab/arrows/function keys etc.

      if (gap > SCAN_GAP_MS) bufferRef.current = "";
      bufferRef.current += e.key;
      if (bufferRef.current.length > 64) bufferRef.current = bufferRef.current.slice(-64);
    };

    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [enabled, onScan]);
}

/**
 * Listens for scan results posted back from the standalone scanner popup
 * window (opened via openStandaloneScanner). Running the camera in a real
 * top-level window sidesteps the embedded preview iframe's permission
 * restrictions, since a popup is a full browsing context of its own.
 */
function useScannerMessageListener(enabled, onScan) {
  useEffect(() => {
    if (!enabled) return undefined;
    const handler = (event) => {
      if (event.data && event.data.source === "workforce-scanner" && typeof event.data.code === "string") {
        onScan(event.data.code);
      }
    };
    window.addEventListener("message", handler);
    return () => window.removeEventListener("message", handler);
  }, [enabled, onScan]);
}

function buildStandaloneScannerHtml() {
  return `<!DOCTYPE html>
<html dir="rtl" lang="ar">
<head>
<meta charset="UTF-8" />
<title>قارئ الباركود المستقل — ${COMPANY_NAME}</title>
<style>
  * { box-sizing: border-box; }
  body { margin:0; background:#15130f; color:#fff; font-family: Tahoma, Arial, sans-serif; display:flex; flex-direction:column; align-items:center; padding:22px 16px; min-height:100vh; }
  h1 { font-size:16px; margin:0 0 4px; display:flex; align-items:center; gap:8px; }
  .count { background: linear-gradient(135deg,#E8622C,#A31E17); border-radius:999px; padding:2px 11px; font-size:12px; display:none; }
  .sub { font-size:12px; color:#c9c0ae; margin:0 0 16px; }
  #reader { position:relative; width:100%; max-width:480px; border-radius:16px; overflow:hidden; box-shadow:0 10px 30px rgba(0,0,0,.4); background:#000; }
  #reader video { width:100% !important; }
  #reader img { display:none !important; }
  .msg { position:relative; width:100%; max-width:480px; display:none; align-items:center; justify-content:center; text-align:center; padding:22px; background:rgba(255,255,255,0.06); border-radius:16px; font-size:13px; line-height:1.7; margin-top:10px; }
  .flash { position:absolute; inset:0; background:rgba(31,157,102,.4); display:flex; align-items:center; justify-content:center; font-size:44px; animation:fl .45s ease-out; z-index:5; }
  @keyframes fl { 0%{opacity:0} 25%{opacity:1} 100%{opacity:0} }
  .controls { display:flex; gap:10px; margin-top:16px; flex-wrap:wrap; justify-content:center; }
  button { border:none; border-radius:10px; padding:11px 20px; font-size:13px; font-weight:700; cursor:pointer; }
  .primary { background: linear-gradient(135deg,#E8622C,#A31E17); color:#fff; }
  .secondary { background:#2b2825; color:#fff; display:none; }
  .manual { margin-top:16px; width:100%; max-width:480px; display:none; }
  .manual input { width:100%; padding:11px; border-radius:9px; border:none; font-size:14px; margin-bottom:8px; }
  .hint { font-size:12px; color:#c9c0ae; margin-top:12px; text-align:center; max-width:480px; line-height:1.8; }
  .brand { position:fixed; top:14px; left:14px; opacity:.5; font-size:11px; letter-spacing:1px; }
</style>
</head>
<body>
  <div class="brand">${COMPANY_NAME}</div>
  <h1>مسح مستمر بالكاميرا <span class="count" id="count">0</span></h1>
  <p class="sub">هذه نافذة مستقلة عن نافذة النظام لضمان عمل الكاميرا بدون قيود — تعمل على كل المتصفحات بما فيها Safari وآيفون.</p>
  <div id="reader"></div>
  <div class="msg" id="msg"></div>
  <div class="controls">
    <button class="secondary" id="switchBtn">تبديل الكاميرا (أمامية/خلفية)</button>
    <button class="primary" id="closeBtn">إنهاء وإغلاق النافذة</button>
  </div>
  <div class="manual" id="manualBox">
    <input id="manualInput" placeholder="اكتب الرقم الظاهر على البطاقة" />
    <button class="primary" id="manualSubmit" style="width:100%">إدخال</button>
  </div>
  <p class="hint" id="hint">جاري تحميل قارئ الباركود...</p>
  <script src="https://unpkg.com/html5-qrcode"></script>
<script>
(function () {
  var switchBtn = document.getElementById('switchBtn');
  var closeBtn = document.getElementById('closeBtn');
  var manualBox = document.getElementById('manualBox');
  var manualInput = document.getElementById('manualInput');
  var manualSubmit = document.getElementById('manualSubmit');
  var hint = document.getElementById('hint');
  var msg = document.getElementById('msg');
  var countEl = document.getElementById('count');
  var facingMode = 'environment';
  var count = 0;
  var cooldownUntil = 0;
  var html5QrCode = null;

  function send(code) {
    var now = Date.now();
    if (now < cooldownUntil) return;
    cooldownUntil = now + 1200;
    count++;
    countEl.style.display = 'inline-block';
    countEl.textContent = count;
    flash();
    try { window.opener && window.opener.postMessage({ source: 'workforce-scanner', code: code }, '*'); } catch (e) {}
    if (html5QrCode && html5QrCode.pause) {
      try {
        html5QrCode.pause(true);
        setTimeout(function () { try { html5QrCode.resume(); } catch (e) {} }, 1200);
      } catch (e) {}
    }
  }

  function flash() {
    var wrap = document.getElementById('reader');
    var f = document.createElement('div');
    f.className = 'flash';
    f.textContent = '\\u2714';
    wrap.appendChild(f);
    setTimeout(function () { f.remove(); }, 450);
  }

  function showError(text) {
    hint.style.display = 'none';
    msg.style.display = 'flex';
    msg.textContent = text;
    manualBox.style.display = 'block';
    manualInput.focus();
  }

  function start(mode) {
    hint.style.display = 'block';
    hint.textContent = 'جاري تشغيل الكاميرا...';
    msg.style.display = 'none';
    if (typeof Html5Qrcode === 'undefined') {
      showError('تعذّر تحميل مكوّن الكاميرا (تحقق من اتصال الإنترنت). أدخل الرقم يدوياً بالأسفل.');
      return;
    }
    var config = {
      fps: 10,
      qrbox: { width: 260, height: 260 },
      aspectRatio: 1.333,
      formatsToSupport: [
        Html5QrcodeSupportedFormats.QR_CODE,
        Html5QrcodeSupportedFormats.CODE_128,
        Html5QrcodeSupportedFormats.CODE_39,
        Html5QrcodeSupportedFormats.EAN_13,
        Html5QrcodeSupportedFormats.EAN_8,
        Html5QrcodeSupportedFormats.UPC_A,
        Html5QrcodeSupportedFormats.UPC_E,
        Html5QrcodeSupportedFormats.CODABAR,
        Html5QrcodeSupportedFormats.ITF
      ]
    };
    var doStart = function () {
      html5QrCode = new Html5Qrcode('reader', { verbose: false });
      html5QrCode.start(
        { facingMode: mode },
        config,
        function (decodedText) { send(decodedText); },
        function () {}
      ).then(function () {
        switchBtn.style.display = 'inline-block';
        hint.textContent = 'وجّه الكاميرا نحو الباركود — يستمر المسح تلقائياً لكل بطاقة دون إغلاق النافذة.';
      }).catch(function (err) {
        var m = String((err && err.message) || err || '').toLowerCase();
        if (m.indexOf('permission') !== -1 || m.indexOf('notallowed') !== -1 || m.indexOf('denied') !== -1) {
          showError('تم رفض إذن الكاميرا. افتح إعدادات المتصفح واسمح بالوصول للكاميرا لهذا الموقع، ثم أعد المحاولة.');
        } else {
          showError('تعذّر تشغيل الكاميرا. تأكد أنها غير مستخدمة في تطبيق آخر.');
        }
      });
    };
    if (html5QrCode) {
      html5QrCode.stop().then(function () { html5QrCode.clear(); doStart(); }).catch(doStart);
    } else {
      doStart();
    }
  }

  switchBtn.onclick = function () { facingMode = facingMode === 'environment' ? 'user' : 'environment'; start(facingMode); };
  closeBtn.onclick = function () {
    if (html5QrCode) { try { html5QrCode.stop(); } catch (e) {} }
    window.close();
  };
  manualSubmit.onclick = function () {
    var v = manualInput.value.trim();
    if (v) { send(v); manualInput.value = ''; manualInput.focus(); }
  };
  manualInput.addEventListener('keydown', function (e) { if (e.key === 'Enter') manualSubmit.onclick(); });

  start(facingMode);
  window.addEventListener('beforeunload', function () { if (html5QrCode) { try { html5QrCode.stop(); } catch (e) {} } });
})();
</script>
</body>
</html>`;
}

function openStandaloneScanner(onPopupBlocked) {
  const html = buildStandaloneScannerHtml();
  const blob = new Blob([html], { type: "text/html" });
  const url = URL.createObjectURL(blob);
  const win = window.open(url, "workforce-scanner-window", "width=520,height=760");
  if (!win) {
    if (onPopupBlocked) onPopupBlocked();
  }
  setTimeout(() => URL.revokeObjectURL(url), 60000);
}

function resizeImageFile(file, maxDim = 220, quality = 0.78) {
  return new Promise((resolve, reject) => {
    if (!file) {
      reject(new Error("ملف غير صالح"));
      return;
    }
    const reader = new FileReader();
    reader.onerror = () => reject(new Error("تعذّرت قراءة الصورة"));
    reader.onload = () => {
      const img = new Image();
      img.onerror = () => reject(new Error("تعذّر تحميل الصورة"));
      img.onload = () => {
        let { width, height } = img;
        if (width > height && width > maxDim) {
          height = Math.round((height * maxDim) / width);
          width = maxDim;
        } else if (height > maxDim) {
          width = Math.round((width * maxDim) / height);
          height = maxDim;
        }
        const canvas = document.createElement("canvas");
        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext("2d");
        ctx.drawImage(img, 0, 0, width, height);
        resolve(canvas.toDataURL("image/jpeg", quality));
      };
      img.src = reader.result;
    };
    reader.readAsDataURL(file);
  });
}

async function fetchImageAsDataUrl(url) {
  const res = await fetch(url, { mode: "cors" });
  if (!res.ok) throw new Error("HTTP " + res.status);
  const blob = await res.blob();
  return resizeImageFile(blob);
}

function downloadBlob(data, filename, type) {
  const blob = new Blob([data], { type });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  setTimeout(() => URL.revokeObjectURL(url), 2000);
}

function exportEmployeesToXlsx(employees, departments, filename) {
  const deptName = (id) => departments.find((d) => d.id === id)?.name || "";
  const rows = employees.map((e) => ({
    "الرقم الوظيفي": e.empNo,
    "رمز الباركود": e.barcode || "",
    "الاسم": e.name,
    "القسم": deptName(e.deptId),
    "الهاتف": e.phone || "",
    "الحالة": e.status === "present" ? "موجود" : "غائب",
  }));
  const ws = XLSX.utils.json_to_sheet(rows);
  ws["!cols"] = [{ wch: 14 }, { wch: 16 }, { wch: 26 }, { wch: 20 }, { wch: 16 }, { wch: 10 }];
  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, "الموظفون");
  const out = XLSX.write(wb, { bookType: "xlsx", type: "array" });
  downloadBlob(out, filename, "application/octet-stream");
}

