let html5QrcodeLoadPromise = null;
function loadHtml5Qrcode() {
  if (typeof window !== "undefined" && window.Html5Qrcode) return Promise.resolve(window.Html5Qrcode);
  if (html5QrcodeLoadPromise) return html5QrcodeLoadPromise;
  html5QrcodeLoadPromise = new Promise((resolve, reject) => {
    const existing = document.querySelector('script[data-html5-qrcode-loader="true"]');
    if (existing) {
      existing.addEventListener("load", () => (window.Html5Qrcode ? resolve(window.Html5Qrcode) : reject(new Error("load-failed"))));
      existing.addEventListener("error", () => reject(new Error("load-failed")));
      return;
    }
    const script = document.createElement("script");
    script.src = "https://unpkg.com/html5-qrcode";
    script.async = true;
    script.dataset.html5QrcodeLoader = "true";
    script.onload = () => {
      if (window.Html5Qrcode) resolve(window.Html5Qrcode);
      else reject(new Error("Html5Qrcode not found on window after script load"));
    };
    script.onerror = () => reject(new Error("تعذّر تحميل مكتبة قراءة الباركود من الإنترنت"));
    document.head.appendChild(script);
  });
  return html5QrcodeLoadPromise;
}

function CameraScannerModal({ onDetect, onClose }) {
  const containerId = useRef(`html5qr-${uid()}`).current;
  const scannerRef = useRef(null);
  const cooldownUntilRef = useRef(0);
  const manualInputRef = useRef(null);
  const mountedRef = useRef(true);
  const [facingMode, setFacingMode] = useState("environment");
  const [status, setStatus] = useState("loading"); // loading | requesting | live | denied | error | unsupported
  const [manualCode, setManualCode] = useState("");
  const [scannedCount, setScannedCount] = useState(0);
  const [flash, setFlash] = useState(false);

  // Continuous mode: every detection is reported to the parent but the
  // camera keeps running — a short cooldown (and a pause/resume of the
  // scanner itself when supported) avoids re-firing on the same
  // still-visible card before the operator moves to the next person.
  const handleDetected = (value) => {
    const now = Date.now();
    if (now < cooldownUntilRef.current) return;
    cooldownUntilRef.current = now + 1200;
    setScannedCount((c) => c + 1);
    setFlash(true);
    setTimeout(() => setFlash(false), 450);
    try {
      if (scannerRef.current && typeof scannerRef.current.pause === "function") {
        scannerRef.current.pause(true);
        setTimeout(() => {
          try {
            scannerRef.current && scannerRef.current.resume && scannerRef.current.resume();
          } catch (e) {
            /* ignore */
          }
        }, 1200);
      }
    } catch (e) {
      /* ignore */
    }
    onDetect(value);
  };

  const stopScanner = async () => {
    try {
      if (scannerRef.current && scannerRef.current.isScanning) {
        await scannerRef.current.stop();
      }
      if (scannerRef.current) scannerRef.current.clear();
    } catch (e) {
      /* ignore */
    }
  };

  const startScanning = async (mode) => {
    setStatus((s) => (s === "loading" ? "loading" : "requesting"));
    try {
      const Html5Qrcode = await loadHtml5Qrcode();
      if (!mountedRef.current) return;
      setStatus("requesting");
      if (!scannerRef.current) {
        scannerRef.current = new Html5Qrcode(containerId, { verbose: false });
      } else if (scannerRef.current.isScanning) {
        await scannerRef.current.stop();
      }
      await scannerRef.current.start(
        { facingMode: mode },
        { fps: 10, qrbox: { width: 250, height: 250 }, aspectRatio: 1.333 },
        (decodedText) => handleDetected(decodedText),
        () => {} // per-frame "nothing found" callback — expected constantly, ignore
      );
      if (!mountedRef.current) return;
      setStatus("live");
    } catch (err) {
      if (!mountedRef.current) return;
      const msg = String((err && err.message) || err || "").toLowerCase();
      if (msg.includes("permission") || msg.includes("notallowed") || msg.includes("denied")) {
        setStatus("denied");
      } else if (msg.includes("تحميل") || msg.includes("load")) {
        setStatus("unsupported");
      } else {
        setStatus("error");
      }
    }
  };

  useEffect(() => {
    mountedRef.current = true;
    startScanning(facingMode);
    return () => {
      mountedRef.current = false;
      stopScanner();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    if (status !== "live") manualInputRef.current?.focus();
  }, [status]);

  const switchCamera = () => {
    const next = facingMode === "environment" ? "user" : "environment";
    setFacingMode(next);
    startScanning(next);
  };

  const submitManual = () => {
    if (!manualCode.trim()) return;
    handleDetected(manualCode.trim());
    setManualCode("");
    manualInputRef.current?.focus();
  };

  const close = async () => {
    await stopScanner();
    onClose();
  };

  return (
    <div className="modal-overlay" onClick={close}>
      <div className="modal-box camera-modal" onClick={(e) => e.stopPropagation()}>
        <div className="modal-head">
          <h3>
            <Camera size={16} style={{ verticalAlign: "-2px", marginLeft: 6 }} /> مسح مستمر بالكاميرا
            {scannedCount > 0 && <span className="scan-count-badge">{scannedCount}</span>}
          </h3>
          <button className="icon-btn" onClick={close}>
            <X size={18} />
          </button>
        </div>

        <div className="camera-view-wrap">
          <div id={containerId} className="html5qr-container" />
          {status === "live" && flash && (
            <div className="camera-flash">
              <CheckCircle2 size={46} />
            </div>
          )}
          {(status === "loading" || status === "requesting") && (
            <div className="camera-overlay-msg">
              {status === "loading" ? "جاري تحميل قارئ الباركود..." : "جاري طلب إذن الوصول للكاميرا..."}
            </div>
          )}
          {status === "denied" && (
            <div className="camera-overlay-msg error">
              <VideoOff size={22} style={{ marginBottom: 8 }} />
              تم رفض إذن الكاميرا. افتح إعدادات المتصفح واسمح بالوصول للكاميرا لهذا الموقع، ثم أعد المحاولة.
            </div>
          )}
          {status === "error" && (
            <div className="camera-overlay-msg error">
              <VideoOff size={22} style={{ marginBottom: 8 }} />
              تعذّر تشغيل الكاميرا. تأكد أنها غير مستخدمة في تطبيق آخر وأعد المحاولة.
            </div>
          )}
          {status === "unsupported" && (
            <div className="camera-overlay-msg error">
              <VideoOff size={22} style={{ marginBottom: 8 }} />
              تعذّر تحميل مكتبة قراءة الباركود (تحقق من الاتصال بالإنترنت). يمكنك إدخال الرقم يدوياً بالأسفل، أو تجربة "فتح في نافذة مستقلة".
            </div>
          )}
        </div>

        <div className="camera-controls">
          <button className="btn btn-secondary" onClick={switchCamera} disabled={status !== "live"}>
            <SwitchCamera size={14} /> تبديل الكاميرا (أمامية/خلفية)
          </button>
          {status !== "live" && status !== "loading" && status !== "requesting" && (
            <button className="btn btn-primary" onClick={() => startScanning(facingMode)}>
              إعادة المحاولة
            </button>
          )}
          {status === "live" && (
            <button className="btn btn-primary" onClick={close}>
              <X size={14} /> إنهاء الجلسة
            </button>
          )}
        </div>

        <div className="camera-manual-fallback">
          <p className="field-hint">
            {status === "live"
              ? "يمكنك أيضاً كتابة الرقم يدوياً إن أردت تجاوز المسح لعامل معيّن:"
              : "بإمكانك إدخال الرقم يدوياً بينما تُحل مشكلة الكاميرا:"}
          </p>
          <div className="camera-manual-row">
            <input
              ref={manualInputRef}
              className="input"
              placeholder="اكتب الرقم الظاهر على البطاقة"
              value={manualCode}
              onChange={(e) => setManualCode(e.target.value)}
              onKeyDown={(e) => { if (e.key === "Enter") submitManual(); }}
            />
            <button className="btn btn-primary" onClick={submitManual}>إدخال</button>
          </div>
        </div>

        {status === "live" && (
          <p className="field-hint camera-hint-center">
            وضع المسح المستمر مفعّل ويعمل على كل المتصفحات بما فيها Safari وآيفون — وجّه الكاميرا نحو كل بطاقة بالتتابع، ستبقى الكاميرا مفتوحة تلقائياً لمسح العامل التالي فوراً. اضغط "إنهاء الجلسة" عند الانتهاء.
          </p>
        )}
      </div>
    </div>
  );
}

