function EmployeeFormModal({ initial, departments, onSave, onClose }) {
  const [empNo, setEmpNo] = useState(initial?.empNo || "");
  const [barcode, setBarcode] = useState(initial?.barcode || "");
  const [name, setName] = useState(initial?.name || "");
  const [deptId, setDeptId] = useState(initial?.deptId || departments[0]?.id || "");
  const [phone, setPhone] = useState(initial?.phone || "");
  const [status, setStatus] = useState(initial?.status || "absent");
  const [photo, setPhoto] = useState(initial?.photo || "");
  const [error, setError] = useState("");
  const photoInputRef = useRef(null);

  const handlePhotoPick = async (file) => {
    if (!file) return;
    try {
      const dataUrl = await resizeImageFile(file);
      setPhoto(dataUrl);
    } catch (err) {
      setError("تعذّر تحميل الصورة، يرجى اختيار صورة أخرى");
    }
  };

  const submit = () => {
    if (!empNo.trim() || !name.trim()) {
      setError("الرقم الوظيفي واسم العامل مطلوبان");
      return;
    }
    if (!deptId) {
      setError("يرجى اختيار القسم");
      return;
    }
    onSave({
      id: initial?.id || uid(),
      empNo: empNo.trim(),
      barcode: barcode.trim(),
      name: name.trim(),
      deptId,
      phone: phone.trim(),
      status,
      photo,
      checkInTime: status === "present" ? initial?.checkInTime || nowTimeStr() : null,
      checkOutTime: status === "present" ? null : initial?.checkOutTime || null,
    });
  };

  return (
    <Modal title={initial ? "تعديل بيانات العامل" : "إضافة عامل جديد"} onClose={onClose}>
      <div className="photo-uploader">
        <div className="photo-avatar" onClick={() => photoInputRef.current?.click()}>
          {photo ? <img src={photo} alt={name || "صورة العامل"} /> : <UserRound size={30} />}
          <div className="photo-avatar-overlay">
            <Camera size={16} />
          </div>
        </div>
        <div className="photo-uploader-actions">
          <button type="button" className="btn btn-secondary" onClick={() => photoInputRef.current?.click()}>
            <Camera size={14} /> {photo ? "تغيير الصورة" : "إضافة صورة"}
          </button>
          {photo && (
            <button type="button" className="btn btn-secondary" onClick={() => setPhoto("")}>
              إزالة
            </button>
          )}
        </div>
        <input
          ref={photoInputRef}
          type="file"
          accept="image/*"
          className="hidden-file-input"
          onChange={(e) => { handlePhotoPick(e.target.files[0]); e.target.value = ""; }}
        />
      </div>
      <div className="form-grid">
        <label className="field">
          <span>الرقم الوظيفي</span>
          <input className="input" value={empNo} onChange={(e) => setEmpNo(e.target.value)} placeholder="مثال: 1042" />
        </label>
        <label className="field">
          <span>رمز الباركود (اختياري)</span>
          <input className="input" value={barcode} onChange={(e) => setBarcode(e.target.value)} placeholder="اتركه فارغاً إذا كان الباركود = الرقم الوظيفي نفسه" />
          <span className="field-hint">إن كانت القيمة المطبوعة على بطاقة العامل مختلفة عن الرقم الوظيفي، أدخلها هنا — سيتم استخدامها عند المسح.</span>
        </label>
        <label className="field">
          <span>اسم العامل</span>
          <input className="input" value={name} onChange={(e) => setName(e.target.value)} placeholder="الاسم الكامل" />
        </label>
        <label className="field">
          <span>القسم</span>
          <select className="select" value={deptId} onChange={(e) => setDeptId(e.target.value)}>
            {departments.length === 0 && <option value="">لا توجد أقسام</option>}
            {departments.map((d) => (
              <option key={d.id} value={d.id}>
                {d.name}
              </option>
            ))}
          </select>
        </label>
        <label className="field">
          <span>رقم الهاتف</span>
          <input className="input" value={phone} onChange={(e) => setPhone(e.target.value)} placeholder="05xxxxxxxx" />
        </label>
        <label className="field">
          <span>الحالة</span>
          <div className="segmented">
            <button
              type="button"
              className={status === "present" ? "seg-active seg-present" : ""}
              onClick={() => setStatus("present")}
            >
              موجود
            </button>
            <button
              type="button"
              className={status === "absent" ? "seg-active seg-absent" : ""}
              onClick={() => setStatus("absent")}
            >
              غائب
            </button>
          </div>
        </label>
      </div>
      {error && <div className="form-error">{error}</div>}
      <div className="modal-actions">
        <button className="btn btn-secondary" onClick={onClose}>
          إلغاء
        </button>
        <button className="btn btn-primary" onClick={submit}>
          حفظ
        </button>
      </div>
    </Modal>
  );
}

