function getArchivedDay(dailyArchive, date) {
  return dailyArchive && dailyArchive[date] ? dailyArchive[date] : null;
}

function shiftDateStr(dateStr, delta) {
  const d = new Date(`${dateStr}T12:00:00`);
  d.setDate(d.getDate() + delta);
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
}

function DateNavigator({ date, onChange, max }) {
  return (
    <div className="date-nav">
      <button className="icon-btn" onClick={() => onChange(shiftDateStr(date, -1))} title="اليوم السابق">
        <ChevronRight size={16} />
      </button>
      <input
        type="date"
        className="date-input"
        value={date}
        max={max}
        onChange={(e) => e.target.value && onChange(e.target.value)}
      />
      <button className="icon-btn" onClick={() => onChange(shiftDateStr(date, 1))} disabled={date >= max} title="اليوم التالي">
        <ChevronLeft size={16} />
      </button>
      {date !== max && (
        <button className="btn btn-secondary date-today-btn" onClick={() => onChange(max)}>
          <CalendarDays size={14} /> اليوم
        </button>
      )}
    </div>
  );
}

function DashboardPage({ employees, departments, onCheckIn, onCheckOut, scanFeedback, recentScans, dailyArchive, todayDate }) {
  const [barcode, setBarcode] = useState("");
  const [mode, setMode] = useState("in");
  const [dashTab, setDashTab] = useState("scan");
  const [selectedDate, setSelectedDate] = useState(todayDate);
  const [showCamera, setShowCamera] = useState(false);
  const [popupBlocked, setPopupBlocked] = useState(false);
  const [recentSearch, setRecentSearch] = useState("");
  const [archiveSearch, setArchiveSearch] = useState("");
  const inputRef = useRef(null);
  const isToday = selectedDate === todayDate;

  useEffect(() => {
    if (isToday) inputRef.current?.focus();
  }, [mode, isToday]);

  const submitScan = () => {
    if (!barcode.trim()) return;
    if (mode === "in") onCheckIn(barcode);
    else onCheckOut(barcode);
    setBarcode("");
  };

  const handleDetectedCode = (code) => {
    if (mode === "in") onCheckIn(code);
    else onCheckOut(code);
  };

  useScannerMessageListener(isToday, handleDetectedCode);

  const pickSuggestion = (emp) => {
    handleDetectedCode(emp.barcode || emp.empNo);
    setBarcode("");
    inputRef.current?.focus();
  };

  const nameSuggestions = useMemo(() => {
    const q = barcode.trim().toLowerCase();
    if (!isToday || q.length < 2) return [];
    return employees
      .filter(
        (e) =>
          e.name.toLowerCase().includes(q) ||
          e.empNo.toLowerCase().includes(q) ||
          (e.barcode && e.barcode.toLowerCase().includes(q))
      )
      .slice(0, 8);
  }, [barcode, employees, isToday]);

  useHardwareScanner(isToday && !showCamera, handleDetectedCode);

  const archived = !isToday ? getArchivedDay(dailyArchive, selectedDate) : null;
  const photoFor = (empId) => employees.find((e) => e.id === empId)?.photo || "";

  const livePresent = employees.filter((e) => e.status === "present").length;
  const liveAbsent = employees.length - livePresent;

  const archPresent = archived ? archived.attendance.filter((a) => a.status === "present").length : 0;
  const archAbsent = archived ? archived.attendance.length - archPresent : 0;
  const archDeptCount = archived ? new Set(archived.attendance.map((a) => a.deptId)).size : 0;

  const filteredRecentScans = useMemo(() => {
    const q = recentSearch.trim().toLowerCase();
    if (!q) return recentScans;
    return recentScans.filter((e) => e.name.toLowerCase().includes(q) || e.empNo.toLowerCase().includes(q));
  }, [recentScans, recentSearch]);

  const archActiveAttendance = useMemo(
    () => (archived ? archived.attendance.filter((a) => a.checkInTime || a.checkOutTime) : []),
    [archived]
  );

  const filteredArchiveAttendance = useMemo(() => {
    const q = archiveSearch.trim().toLowerCase();
    if (!q) return archActiveAttendance;
    return archActiveAttendance.filter((a) => a.name.toLowerCase().includes(q) || a.empNo.toLowerCase().includes(q));
  }, [archActiveAttendance, archiveSearch]);

  return (
    <div className="page">
      <div className="page-header">
        <div>
          <h1>لوحة التحكم</h1>
          <p className="page-sub">{arabicDate(selectedDate)}</p>
        </div>
        <DateNavigator date={selectedDate} onChange={setSelectedDate} max={todayDate} />
      </div>

      {isToday ? (
        <>
          <div className="dash-tabs">
            <button
              type="button"
              className={`dash-tab-btn ${dashTab === "scan" ? "dash-tab-active" : ""}`}
              onClick={() => setDashTab("scan")}
            >
              <ScanLine size={16} /> المسح والحضور
            </button>
            <button
              type="button"
              className={`dash-tab-btn ${dashTab === "overview" ? "dash-tab-active" : ""}`}
              onClick={() => setDashTab("overview")}
            >
              <LayoutDashboard size={16} /> نظرة عامة
            </button>
          </div>

          {dashTab === "overview" && (
            <div className="stats-row">
              <StatCard icon={<Users size={20} />} label="إجمالي الموظفين" value={employees.length} tone="neutral" />
              <StatCard icon={<CheckCircle2 size={20} />} label="الموجودون" value={livePresent} tone="success" />
              <StatCard icon={<XCircle size={20} />} label="الغائبون" value={liveAbsent} tone="danger" />
              <StatCard icon={<Building2 size={20} />} label="عدد الأقسام" value={departments.length} tone="info" />
            </div>
          )}

          {dashTab === "scan" && (
            <>
              <div className="scan-control-bar">
                <div className="scan-corner-actions">
                  <button className="corner-icon-btn" onClick={() => setShowCamera(true)} title="فتح الكاميرا">
                    <Camera size={17} />
                  </button>
                  <button
                    className="corner-icon-btn"
                    onClick={() => openStandaloneScanner(() => setPopupBlocked(true))}
                    title="فتح الكاميرا في نافذة مستقلة (الخيار الأضمن)"
                  >
                    <ExternalLink size={16} />
                  </button>
                </div>

                <div className="scan-control-head">
                  <div className="scan-hero-icon">
                    <ScanLine size={22} />
                  </div>
                  <div>
                    <h2>تسجيل الحضور والانصراف بالباركود</h2>
                    <p>اختر العملية المطلوبة، ثم امسح باركود بطاقة العامل أو أدخل رقمه يدوياً واضغط Enter.</p>
                  </div>
                </div>

                <div className="mode-toggle">
                  <button
                    type="button"
                    className={`mode-btn mode-btn-in ${mode === "in" ? "mode-btn-active" : ""}`}
                    onClick={() => setMode("in")}
                  >
                    <LogIn size={16} /> تسجيل دخول
                  </button>
                  <button
                    type="button"
                    className={`mode-btn mode-btn-out ${mode === "out" ? "mode-btn-active" : ""}`}
                    onClick={() => setMode("out")}
                  >
                    <LogOut size={16} /> تسجيل خروج
                  </button>
                </div>

                <input
                  ref={inputRef}
                  className="scan-input scan-input-full"
                  data-scanner-input="true"
                  placeholder={mode === "in" ? "امسح الباركود، أو أدخل الرقم الوظيفي، أو اكتب اسم العامل..." : "امسح الباركود، أو أدخل الرقم الوظيفي، أو اكتب اسم العامل..."}
                  value={barcode}
                  onChange={(e) => setBarcode(e.target.value)}
                  onKeyDown={(e) => { if (e.key === "Enter") submitScan(); }}
                />

                {popupBlocked && (
                  <div className="scan-feedback error">
                    <AlertTriangle size={16} /> المتصفح منع فتح النافذة المنبثقة. يرجى السماح بالنوافذ المنبثقة (Pop-ups) لهذا الموقع من إعدادات المتصفح، ثم إعادة الضغط على الزر.
                  </div>
                )}

                {nameSuggestions.length > 0 && (
                  <div className="suggestion-list scan-suggestion-list">
                    {nameSuggestions.map((e) => (
                      <button key={e.id} className="suggestion-item" onClick={() => pickSuggestion(e)}>
                        <span>{e.name}</span>
                        <span className="suggestion-meta">
                          {departments.find((d) => d.id === e.deptId)?.name || "—"} ·{" "}
                          {e.status === "present" ? "موجود" : "غائب"}
                        </span>
                      </button>
                    ))}
                  </div>
                )}

                {scanFeedback && scanFeedback.type === "error" && (
                  <div className="scan-feedback error">
                    <AlertTriangle size={16} /> {scanFeedback.message}
                  </div>
                )}
              </div>

              <div className="scan-result-hero">
                {!scanFeedback || scanFeedback.type === "error" ? (
                  <div className="hero-idle">
                    <div className="hero-idle-avatar">
                      <UserRound size={64} />
                    </div>
                    <p>{scanFeedback?.type === "error" ? `لم يتم العثور على "${scanFeedback.code}"` : "بانتظار المسح..."}</p>
                  </div>
                ) : (
                  <div className={`hero-result hero-result-${scanFeedback.op}`}>
                    <Avatar src={scanFeedback.photo} size="hero" />
                    <div className="hero-result-name">{scanFeedback.name}</div>
                    <div className="hero-result-meta">{scanFeedback.empNo} · {scanFeedback.deptName}</div>
                    <div className={`hero-result-badge ${scanFeedback.op === "in" ? "badge-hero-in" : "badge-hero-out"}`}>
                      {scanFeedback.op === "in" ? <LogIn size={18} /> : <LogOut size={18} />}
                      {scanFeedback.op === "in" ? "دخول" : "خروج"} — {scanFeedback.time}
                    </div>
                    <div className="hero-result-msg">{scanFeedback.message}</div>
                  </div>
                )}
              </div>

              {showCamera && (
                <CameraScannerModal onDetect={handleDetectedCode} onClose={() => setShowCamera(false)} />
              )}

              <div className="card">
                <div className="card-head">
                  <h3>كل عمليات الدخول والخروج اليوم</h3>
                  {recentScans.length > 0 && (
                    <div className="search-box recent-search-box">
                      <Search size={14} />
                      <input
                        placeholder="ابحث بالاسم أو الرقم الوظيفي..."
                        value={recentSearch}
                        onChange={(e) => setRecentSearch(e.target.value)}
                      />
                    </div>
                  )}
                </div>
                {recentScans.length === 0 ? (
                  <EmptyState icon={<Clock3 size={30} />} title="لا توجد عمليات بعد" hint="ستظهر هنا كل عمليات المسح لهذا اليوم" />
                ) : filteredRecentScans.length === 0 ? (
                  <EmptyState icon={<Search size={30} />} title="لا توجد نتائج مطابقة" />
                ) : (
                  <div className="table-wrap">
                    <table className="table">
                      <thead>
                        <tr>
                          <th></th>
                          <th>الرقم الوظيفي</th>
                          <th>الاسم</th>
                          <th>القسم</th>
                          <th>العملية</th>
                          <th>الوقت</th>
                        </tr>
                      </thead>
                      <tbody>
                        {filteredRecentScans.map((e, idx) => (
                          <tr key={`${e.id}-${idx}`}>
                            <td><Avatar src={e.photo} size="sm" /></td>
                            <td>{e.empNo}</td>
                            <td>{e.name}</td>
                            <td>{e.deptName}</td>
                            <td>
                              {e.type === "in" ? (
                                <span className="badge badge-present"><LogIn size={12} /> دخول</span>
                              ) : (
                                <span className="badge badge-out"><LogOut size={12} /> خروج</span>
                              )}
                            </td>
                            <td>{e.time}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                )}
              </div>
            </>
          )}
        </>
      ) : (
        <>
          <div className="stats-row">
            <StatCard icon={<Users size={20} />} label="إجمالي المسجَّلين" value={archived ? archived.attendance.length : 0} tone="neutral" />
            <StatCard icon={<CheckCircle2 size={20} />} label="كانوا موجودين" value={archPresent} tone="success" />
            <StatCard icon={<XCircle size={20} />} label="كانوا غائبين" value={archAbsent} tone="danger" />
            <StatCard icon={<Building2 size={20} />} label="عدد الأقسام" value={archDeptCount} tone="info" />
          </div>

          <div className="historical-banner">
            <History size={16} />
            <span>أنت تستعرض سجل يوم <b>{arabicDate(selectedDate)}</b> — المسح متاح فقط لليوم الحالي.</span>
            <button className="btn btn-secondary" onClick={() => setSelectedDate(todayDate)}>العودة لليوم الحالي</button>
          </div>

          <div className="card">
            <div className="card-head">
              <h3>سجل الحضور والانصراف ليوم {selectedDate}</h3>
              {archActiveAttendance.length > 0 && (
                <div className="search-box recent-search-box">
                  <Search size={14} />
                  <input
                    placeholder="ابحث بالاسم أو الرقم الوظيفي..."
                    value={archiveSearch}
                    onChange={(e) => setArchiveSearch(e.target.value)}
                  />
                </div>
              )}
            </div>
            {!archived || archived.attendance.length === 0 ? (
              <EmptyState icon={<History size={30} />} title="لا توجد بيانات مسجلة لهذا اليوم" hint="لم يكن هناك موظفون أو حركة حضور محفوظة في هذا التاريخ" />
            ) : archActiveAttendance.length === 0 ? (
              <EmptyState icon={<History size={30} />} title="لم يسجّل أي عامل حضوره في هذا اليوم" hint="القائمة هنا تعرض فقط من له حركة دخول أو خروج فعلية" />
            ) : filteredArchiveAttendance.length === 0 ? (
              <EmptyState icon={<Search size={30} />} title="لا توجد نتائج مطابقة" />
            ) : (
              <div className="table-wrap">
                <table className="table">
                  <thead>
                    <tr>
                      <th></th>
                      <th>الرقم الوظيفي</th>
                      <th>الاسم</th>
                      <th>القسم</th>
                      <th>الحالة</th>
                      <th>وقت الدخول</th>
                      <th>وقت الخروج</th>
                    </tr>
                  </thead>
                  <tbody>
                    {filteredArchiveAttendance.map((a) => (
                      <tr key={a.empId}>
                        <td><Avatar src={photoFor(a.empId)} size="sm" /></td>
                        <td>{a.empNo}</td>
                        <td>{a.name}</td>
                        <td>{a.deptName}</td>
                        <td>
                          {a.status === "present" ? (
                            <span className="badge badge-present"><CheckCircle2 size={12} /> موجود</span>
                          ) : (
                            <span className="badge badge-absent"><XCircle size={12} /> غائب</span>
                          )}
                        </td>
                        <td>{a.checkInTime || "—"}</td>
                        <td>{a.checkOutTime || "—"}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </div>
        </>
      )}
    </div>
  );
}

/* ------------------------------------------------------------------ */
/* Employees Page                                                       */
/* ------------------------------------------------------------------ */

const PAGE_SIZE = 25;

function EmployeesPage({ employees, departments, onAdd, onEdit, onDelete, onCheckout, onCheckin }) {
  const [query, setQuery] = useState("");
  const [deptFilter, setDeptFilter] = useState("all");
  const [statusFilter, setStatusFilter] = useState("all");
  const [page, setPage] = useState(1);
  const [editing, setEditing] = useState(null);
  const [showForm, setShowForm] = useState(false);
  const [confirmDelete, setConfirmDelete] = useState(null);

  const deptName = (id) => departments.find((d) => d.id === id)?.name || "—";

  const filtered = useMemo(() => {
    return employees.filter((e) => {
      const matchesQuery =
        !query.trim() ||
        e.name.toLowerCase().includes(query.trim().toLowerCase()) ||
        e.empNo.toLowerCase().includes(query.trim().toLowerCase());
      const matchesDept = deptFilter === "all" || e.deptId === deptFilter;
      const matchesStatus = statusFilter === "all" || e.status === statusFilter;
      return matchesQuery && matchesDept && matchesStatus;
    });
  }, [employees, query, deptFilter, statusFilter]);

  const totalPages = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
  const pageSafe = Math.min(page, totalPages);
  const pageItems = filtered.slice((pageSafe - 1) * PAGE_SIZE, pageSafe * PAGE_SIZE);

  return (
    <div className="page">
      <div className="page-header">
        <div>
          <h1>الموظفون</h1>
          <p className="page-sub">{employees.length} موظف مسجّل في النظام</p>
        </div>
        <button className="btn btn-primary" onClick={() => { setEditing(null); setShowForm(true); }}>
          <Plus size={16} /> إضافة عامل
        </button>
      </div>

      <div className="filters-row">
        <div className="search-box">
          <Search size={16} />
          <input
            placeholder="بحث بالاسم أو الرقم الوظيفي..."
            value={query}
            onChange={(e) => { setQuery(e.target.value); setPage(1); }}
          />
        </div>
        <select className="select" value={deptFilter} onChange={(e) => { setDeptFilter(e.target.value); setPage(1); }}>
          <option value="all">كل الأقسام</option>
          {departments.map((d) => (
            <option key={d.id} value={d.id}>{d.name}</option>
          ))}
        </select>
        <select className="select" value={statusFilter} onChange={(e) => { setStatusFilter(e.target.value); setPage(1); }}>
          <option value="all">كل الحالات</option>
          <option value="present">موجود</option>
          <option value="absent">غائب</option>
        </select>
      </div>

      <div className="card">
        {employees.length === 0 ? (
          <EmptyState icon={<Users size={30} />} title="لا يوجد موظفون بعد" hint="أضف عاملاً جديداً أو استورد ملف إكسيل من صفحة النسخ الاحتياطي" />
        ) : filtered.length === 0 ? (
          <EmptyState icon={<Search size={30} />} title="لا توجد نتائج مطابقة" />
        ) : (
          <>
            <div className="table-wrap">
              <table className="table">
                <thead>
                  <tr>
                    <th></th>
                    <th>الرقم الوظيفي</th>
                    <th>رمز الباركود</th>
                    <th>اسم العامل</th>
                    <th>القسم</th>
                    <th>الحالة</th>
                    <th>وقت الدخول</th>
                    <th>وقت الخروج</th>
                    <th>رقم الهاتف</th>
                    <th></th>
                  </tr>
                </thead>
                <tbody>
                  {pageItems.map((e) => (
                    <tr key={e.id}>
                      <td><Avatar src={e.photo} size="sm" /></td>
                      <td>{e.empNo}</td>
                      <td>{e.barcode ? e.barcode : <span style={{ color: "var(--text-muted)" }}>= الرقم الوظيفي</span>}</td>
                      <td>{e.name}</td>
                      <td>{deptName(e.deptId)}</td>
                      <td>
                        {e.status === "present" ? (
                          <span className="badge badge-present"><CheckCircle2 size={12} /> موجود</span>
                        ) : (
                          <span className="badge badge-absent"><XCircle size={12} /> غائب</span>
                        )}
                      </td>
                      <td>{e.checkInTime || "—"}</td>
                      <td>{e.checkOutTime || "—"}</td>
                      <td>{e.phone || "—"}</td>
                      <td className="row-actions">
                        {e.status === "present" ? (
                          <button
                            className="icon-btn icon-btn-warn"
                            title="تسجيل خروج"
                            onClick={() => onCheckout(e.id)}
                          >
                            <LogOut size={15} />
                          </button>
                        ) : (
                          <button
                            className="icon-btn icon-btn-success"
                            title="تسجيل دخول"
                            onClick={() => onCheckin(e.id)}
                          >
                            <LogIn size={15} />
                          </button>
                        )}
                        <button className="icon-btn" onClick={() => { setEditing(e); setShowForm(true); }}>
                          <Pencil size={15} />
                        </button>
                        <button className="icon-btn icon-btn-danger" onClick={() => setConfirmDelete(e)}>
                          <Trash2 size={15} />
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
            {totalPages > 1 && (
              <div className="pagination">
                <button className="icon-btn" disabled={pageSafe <= 1} onClick={() => setPage(pageSafe - 1)}>
                  <ChevronRight size={16} />
                </button>
                <span>صفحة {pageSafe} من {totalPages}</span>
                <button className="icon-btn" disabled={pageSafe >= totalPages} onClick={() => setPage(pageSafe + 1)}>
                  <ChevronLeft size={16} />
                </button>
              </div>
            )}
          </>
        )}
      </div>

      {showForm && (
        <EmployeeFormModal
          initial={editing}
          departments={departments}
          onClose={() => setShowForm(false)}
          onSave={(emp) => {
            editing ? onEdit(emp) : onAdd(emp);
            setShowForm(false);
          }}
        />
      )}
      {confirmDelete && (
        <ConfirmDialog
          message={`هل تريد حذف العامل "${confirmDelete.name}"؟ لا يمكن التراجع عن هذا الإجراء.`}
          onCancel={() => setConfirmDelete(null)}
          onConfirm={() => { onDelete(confirmDelete.id); setConfirmDelete(null); }}
        />
      )}
    </div>
  );
}

/* ------------------------------------------------------------------ */
/* Departments Page                                                     */
/* ------------------------------------------------------------------ */

function DepartmentsPage({ departments, employees, onAdd, onEdit, onDelete }) {
  const [showForm, setShowForm] = useState(false);
  const [editing, setEditing] = useState(null);
  const [confirmDelete, setConfirmDelete] = useState(null);
  const [blocked, setBlocked] = useState(null);
  const [viewingDept, setViewingDept] = useState(null);

  const countFor = (id) => employees.filter((e) => e.deptId === id).length;
  const employeesFor = (id) => employees.filter((e) => e.deptId === id);

  return (
    <div className="page">
      <div className="page-header">
        <div>
          <h1>الأقسام</h1>
          <p className="page-sub">{departments.length} قسم داخل المنشأة — اضغط على أي قسم لعرض موظفيه</p>
        </div>
        <button className="btn btn-primary" onClick={() => { setEditing(null); setShowForm(true); }}>
          <Plus size={16} /> إضافة قسم
        </button>
      </div>

      {departments.length === 0 ? (
        <div className="card">
          <EmptyState icon={<Building2 size={30} />} title="لا توجد أقسام بعد" hint="ابدأ بإضافة أول قسم لتتمكن من تسجيل الموظفين" />
        </div>
      ) : (
        <div className="dept-grid">
          {departments.map((d) => (
            <div className="dept-card dept-card-clickable" key={d.id} onClick={() => setViewingDept(d)}>
              <div className="dept-card-top">
                <div className="dept-icon"><Building2 size={20} /></div>
                <div className="row-actions">
                  <button
                    className="icon-btn"
                    onClick={(ev) => { ev.stopPropagation(); setEditing(d); setShowForm(true); }}
                  >
                    <Pencil size={14} />
                  </button>
                  <button
                    className="icon-btn icon-btn-danger"
                    onClick={(ev) => {
                      ev.stopPropagation();
                      if (countFor(d.id) > 0) setBlocked(d);
                      else setConfirmDelete(d);
                    }}
                  >
                    <Trash2 size={14} />
                  </button>
                </div>
              </div>
              <div className="dept-name">{d.name}</div>
              <div className="dept-count">{countFor(d.id)} عامل</div>
            </div>
          ))}
        </div>
      )}

      {showForm && (
        <DepartmentFormModal
          initial={editing}
          onClose={() => setShowForm(false)}
          onSave={(dep) => { editing ? onEdit(dep) : onAdd(dep); setShowForm(false); }}
        />
      )}
      {confirmDelete && (
        <ConfirmDialog
          message={`هل تريد حذف قسم "${confirmDelete.name}"؟`}
          onCancel={() => setConfirmDelete(null)}
          onConfirm={() => { onDelete(confirmDelete.id); setConfirmDelete(null); }}
        />
      )}
      {blocked && (
        <Modal title="لا يمكن حذف القسم" onClose={() => setBlocked(null)} width={380}>
          <p style={{ color: "var(--text-muted)", lineHeight: 1.8 }}>
            يضم قسم "{blocked.name}" حالياً {countFor(blocked.id)} عامل. يرجى نقل الموظفين إلى قسم آخر أو حذفهم أولاً.
          </p>
          <div className="modal-actions">
            <button className="btn btn-primary" onClick={() => setBlocked(null)}>حسناً</button>
          </div>
        </Modal>
      )}
      {viewingDept && (
        <Modal title={`موظفو قسم: ${viewingDept.name}`} onClose={() => setViewingDept(null)} width={640}>
          {employeesFor(viewingDept.id).length === 0 ? (
            <EmptyState icon={<Users size={28} />} title="لا يوجد موظفون في هذا القسم بعد" />
          ) : (
            <div className="table-wrap">
              <table className="table table-compact">
                <thead>
                  <tr>
                    <th></th>
                    <th>الرقم الوظيفي</th>
                    <th>الاسم</th>
                    <th>الحالة</th>
                    <th>الهاتف</th>
                  </tr>
                </thead>
                <tbody>
                  {employeesFor(viewingDept.id).map((e) => (
                    <tr key={e.id}>
                      <td><Avatar src={e.photo} size="sm" /></td>
                      <td>{e.empNo}</td>
                      <td>{e.name}</td>
                      <td>
                        {e.status === "present" ? (
                          <span className="badge badge-present"><CheckCircle2 size={12} /> موجود</span>
                        ) : (
                          <span className="badge badge-absent"><XCircle size={12} /> غائب</span>
                        )}
                      </td>
                      <td>{e.phone || "—"}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </Modal>
      )}
    </div>
  );
}

/* ------------------------------------------------------------------ */
/* Meals Page                                                           */
/* ------------------------------------------------------------------ */

function MealsPage({ employees, departments, mealIds, onAddMeal, onRemoveMeal, dailyArchive, todayDate, canEdit }) {
  const [query, setQuery] = useState("");
  const [notice, setNotice] = useState(null);
  const [selectedDate, setSelectedDate] = useState(todayDate);
  const [printBlocked, setPrintBlocked] = useState(false);
  const [showCamera, setShowCamera] = useState(false);
  const [popupBlocked, setPopupBlocked] = useState(false);
  const isToday = selectedDate === todayDate;
  const beep = useBeep();
  const employeeLookup = useMemo(() => buildEmployeeLookup(employees), [employees]);

  const deptName = (id) => departments.find((d) => d.id === id)?.name || "بدون قسم";

  const mealEmployees = useMemo(
    () => mealIds.map((m) => ({ ...m, emp: employees.find((e) => e.id === m.empId) })).filter((m) => m.emp),
    [mealIds, employees]
  );

  const liveGroups = useMemo(() => {
    const map = new Map();
    mealEmployees.forEach((m) => {
      const key = m.emp.deptId || "none";
      if (!map.has(key)) map.set(key, []);
      map.get(key).push({ empId: m.empId, empNo: m.emp.empNo, name: m.emp.name, time: m.time });
    });
    return Array.from(map.entries()).map(([deptId, list]) => ({
      deptId,
      name: deptId === "none" ? "بدون قسم" : deptName(deptId),
      list,
    }));
  }, [mealEmployees, departments]);

  const archived = !isToday ? getArchivedDay(dailyArchive, selectedDate) : null;

  const archivedGroups = useMemo(() => {
    if (isToday || !archived) return [];
    const map = new Map();
    archived.meals.forEach((m) => {
      const key = m.deptId || "none";
      if (!map.has(key)) map.set(key, []);
      map.get(key).push({ empId: m.empId, empNo: m.empNo, name: m.name, time: m.time });
    });
    return Array.from(map.entries()).map(([deptId, list]) => ({
      deptId,
      name: deptId === "none" ? "بدون قسم" : list.find((x) => x)?.deptName || deptName(deptId),
      list,
    }));
  }, [archived, isToday, departments]);

  const effectiveGroups = isToday ? liveGroups : archivedGroups;
  const effectiveTotal = isToday ? mealEmployees.length : archived ? archived.meals.length : 0;

  const suggestions = useMemo(() => {
    if (!isToday || !query.trim()) return [];
    const q = query.trim().toLowerCase();
    return employees
      .filter((e) => e.status === "present")
      .filter((e) => (e.name.toLowerCase().includes(q) || e.empNo.toLowerCase().includes(q)))
      .filter((e) => !mealIds.some((m) => m.empId === e.id))
      .slice(0, 8);
  }, [query, employees, mealIds, isToday]);

  const handleScanOrEnter = () => {
    const q = query.trim();
    if (!q) return;
    const byNo = findEmployeeByCode(employeeLookup, q);
    if (byNo) {
      if (byNo.status !== "present") {
        beep("error");
        setNotice({ type: "error", text: `${byNo.name} مسجّل "غائب" حالياً — يجب تسجيل حضوره أولاً من لوحة التحكم قبل إضافته لقائمة الطعام.` });
        return;
      }
      addEmployee(byNo);
      return;
    }
    if (suggestions.length === 1) addEmployee(suggestions[0]);
    else if (suggestions.length === 0) {
      beep("error");
      setNotice({ type: "error", text: `لا يوجد عامل مطابق للرمز أو الاسم "${q}"` });
    }
  };

  const addEmployee = (emp) => {
    if (emp.status !== "present") {
      beep("error");
      setNotice({ type: "error", text: `${emp.name} مسجّل "غائب" حالياً — يجب تسجيل حضوره أولاً من لوحة التحكم قبل إضافته لقائمة الطعام.` });
      return;
    }
    if (mealIds.some((m) => m.empId === emp.id)) {
      beep("error");
      setNotice({ type: "error", text: `${emp.name} مُضاف لقائمة الطعام مسبقاً اليوم.` });
      return;
    }
    beep("success");
    onAddMeal({ empId: emp.id, time: nowTimeStr() });
    setQuery("");
    setNotice({ type: "success", text: `تمت إضافة ${emp.name} لقائمة الطعام.` });
  };

  useEffect(() => {
    if (!notice) return;
    const t = setTimeout(() => setNotice(null), 3000);
    return () => clearTimeout(t);
  }, [notice]);

  const handleDetectedCode = (code) => {
    const byNo = findEmployeeByCode(employeeLookup, code.trim());
    if (!byNo) {
      beep("error");
      setNotice({ type: "error", text: `لا يوجد عامل بالرمز "${code}"` });
      return;
    }
    addEmployee(byNo);
  };

  useHardwareScanner(isToday && canEdit && !showCamera, handleDetectedCode);
  useScannerMessageListener(isToday && canEdit, handleDetectedCode);

  const escapeHtml = (s) =>
    String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));

  const buildPrintHtml = () => {
    const blocks = effectiveGroups
      .map(
        (g) => `
        <div class="dept-block">
          <h2>${escapeHtml(g.name)} — ${g.list.length} وجبة</h2>
          <table>
            <thead>
              <tr><th>#</th><th>الرقم الوظيفي</th><th>الاسم</th><th>الوقت</th></tr>
            </thead>
            <tbody>
              ${g.list
                .map(
                  (m, idx) => `
                <tr>
                  <td>${idx + 1}</td>
                  <td>${escapeHtml(m.empNo)}</td>
                  <td>${escapeHtml(m.name)}</td>
                  <td>${escapeHtml(m.time)}</td>
                </tr>`
                )
                .join("")}
            </tbody>
          </table>
        </div>`
      )
      .join("");

    return `<!DOCTYPE html>
<html dir="rtl" lang="ar">
<head>
<meta charset="UTF-8" />
<title>قائمة الطعام — ${escapeHtml(selectedDate)}</title>
<style>
  body { font-family: Tahoma, Arial, sans-serif; padding: 24px; color: #16202A; }
  h1 { font-size: 20px; margin: 0 0 2px; }
  .sub-date { color: #555; margin: 0 0 20px; font-size: 13px; }
  .dept-block { break-inside: avoid; margin-bottom: 22px; }
  .dept-block h2 { font-size: 15px; border-bottom: 2px solid #333; padding-bottom: 4px; margin-bottom: 6px; }
  table { width: 100%; border-collapse: collapse; }
  th, td { border: 1px solid #999; padding: 6px 10px; font-size: 12.5px; text-align: right; }
  th { background: #EEE; }
  .total { margin-top: 18px; font-weight: bold; font-size: 14px; }
  .print-btn { margin-bottom: 18px; padding: 8px 18px; font-size: 13px; cursor: pointer; }
  @media print { .print-btn { display: none; } }
</style>
</head>
<body>
  <button class="print-btn" onclick="window.print()">طباعة</button>
  <h1>قائمة الطعام${isToday ? " اليومية" : ""}</h1>
  <p class="sub-date">${escapeHtml(arabicDate(selectedDate))}</p>
  ${blocks || "<p>لا توجد وجبات مسجلة لهذا اليوم.</p>"}
  <p class="total">إجمالي الوجبات: ${effectiveTotal}</p>
  <script>window.onload = function () { setTimeout(function () { window.print(); }, 250); };</script>
</body>
</html>`;
  };

  const handlePrint = () => {
    const html = buildPrintHtml();
    const blob = new Blob([html], { type: "text/html" });
    const url = URL.createObjectURL(blob);
    const win = window.open(url, "_blank");
    if (!win) {
      setPrintBlocked(true);
    } else {
      setPrintBlocked(false);
    }
    setTimeout(() => URL.revokeObjectURL(url), 30000);
  };

  return (
    <div className="page">
      <div className="page-header">
        <div>
          <h1>قائمة الطعام{isToday ? " اليومية" : ""}</h1>
          <p className="page-sub">{arabicDate(selectedDate)}</p>
        </div>
        <div className="header-actions">
          <DateNavigator date={selectedDate} onChange={setSelectedDate} max={todayDate} />
          <div className="meal-total-badge">
            <UtensilsCrossed size={16} /> إجمالي الوجبات: {effectiveTotal}
          </div>
          <button className="btn btn-secondary" onClick={handlePrint}>
            <Printer size={16} /> طباعة القائمة
          </button>
        </div>
      </div>

      {printBlocked && (
        <div className="import-msg error" style={{ marginBottom: 16 }}>
          <AlertTriangle size={16} /> المتصفح منع فتح نافذة الطباعة. يرجى السماح بالنوافذ المنبثقة (Pop-ups) لهذا الموقع من إعدادات المتصفح ثم إعادة الضغط على "طباعة القائمة".
        </div>
      )}

      {!isToday && (
        <div className="historical-banner">
          <History size={16} />
          <span>أنت تستعرض كشف طعام يوم <b>{arabicDate(selectedDate)}</b> — للعرض والطباعة فقط، لا يمكن التعديل عليه.</span>
          <button className="btn btn-secondary" onClick={() => setSelectedDate(todayDate)}>العودة لليوم الحالي</button>
        </div>
      )}

      {isToday && !canEdit && (
        <div className="historical-banner">
          <ShieldAlert size={16} />
          <span>وضع المشغل: تُضاف الوجبات تلقائياً عند تسجيل الحضور من لوحة التحكم. التعديل اليدوي هنا متاح لوضع المسؤول فقط.</span>
        </div>
      )}

      {isToday && canEdit && (
        <div className="card">
          <div className="meal-search">
            <ScanLine size={18} />
            <input
              className="scan-input-inline"
              data-scanner-input="true"
              placeholder="امسح باركود العامل أو اكتب اسمه / رقمه الوظيفي..."
              value={query}
              onChange={(e) => { setQuery(e.target.value); setNotice(null); }}
              onKeyDown={(e) => { if (e.key === "Enter") handleScanOrEnter(); }}
            />
            <button type="button" className="camera-btn camera-btn-inline" onClick={() => setShowCamera(true)}>
              <Camera size={16} /> الكاميرا
            </button>
            <button
              type="button"
              className="camera-btn camera-btn-inline camera-btn-popup-inline"
              onClick={() => openStandaloneScanner(() => setPopupBlocked(true))}
              title="يفتح الكاميرا في نافذة مستقلة — الخيار الأضمن إن واجهت مشكلة في فتح الكاميرا هنا"
            >
              <ExternalLink size={15} /> نافذة مستقلة
            </button>
          </div>
          {popupBlocked && (
            <div className="import-msg error" style={{ marginTop: 10 }}>
              <AlertTriangle size={16} /> المتصفح منع فتح النافذة المنبثقة. يرجى السماح بالنوافذ المنبثقة (Pop-ups) لهذا الموقع من إعدادات المتصفح، ثم إعادة الضغط على الزر.
            </div>
          )}
          <p className="meal-search-hint">تظهر في نتائج البحث الأسماء المسجّل حضورها اليوم فقط</p>
          {notice && (
            <div className={`import-msg ${notice.type}`} style={{ marginTop: 10 }}>
              <AlertTriangle size={16} /> {notice.text}
            </div>
          )}
          {suggestions.length > 0 && (
            <div className="suggestion-list">
              {suggestions.map((e) => (
                <button key={e.id} className="suggestion-item" onClick={() => addEmployee(e)}>
                  <span>{e.name}</span>
                  <span className="suggestion-meta">{e.empNo} · {deptName(e.deptId)}</span>
                </button>
              ))}
            </div>
          )}
        </div>
      )}

      {showCamera && (
        <CameraScannerModal onDetect={handleDetectedCode} onClose={() => setShowCamera(false)} />
      )}

      {effectiveGroups.length === 0 ? (
        <div className="card">
          <EmptyState
            icon={<UtensilsCrossed size={30} />}
            title={isToday ? "لم تتم إضافة أي وجبات اليوم" : "لا توجد بيانات وجبات مسجلة لهذا اليوم"}
            hint={isToday && canEdit ? "ابحث عن العامل أعلاه أو امسح باركوده لإضافته للقائمة" : isToday ? "ستُضاف الوجبات تلقائياً عند تسجيل الحضور من لوحة التحكم" : undefined}
          />
        </div>
      ) : (
        <div className="meal-grid">
          {effectiveGroups.map((g) => (
            <div className="card meal-dept-card" key={g.deptId}>
              <div className="meal-dept-head">
                <h3>{g.name}</h3>
                <span className="dept-badge-count">{g.list.length}</span>
              </div>
              <table className="table table-compact">
                <thead>
                  <tr>
                    <th>الرقم الوظيفي</th>
                    <th>الاسم</th>
                    <th>الوقت</th>
                    {isToday && canEdit && <th></th>}
                  </tr>
                </thead>
                <tbody>
                  {g.list.map((m) => (
                    <tr key={m.empId}>
                      <td>{m.empNo}</td>
                      <td>{m.name}</td>
                      <td>{m.time}</td>
                      {isToday && canEdit && (
                        <td>
                          <button className="icon-btn icon-btn-danger" onClick={() => onRemoveMeal(m.empId)}>
                            <X size={13} />
                          </button>
                        </td>
                      )}
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

/* ------------------------------------------------------------------ */
/* Backup & Import Page                                                 */
/* ------------------------------------------------------------------ */

function BackupPage({ employees, departments, onBulkImport, onRestoreAll, onChangePin, onChangeAdminPin }) {
  const [importMsg, setImportMsg] = useState(null);
  const [importing, setImporting] = useState(false);
  const [currentPin, setCurrentPin] = useState("");
  const [newPin, setNewPin] = useState("");
  const [confirmPin, setConfirmPin] = useState("");
  const [pinMsg, setPinMsg] = useState(null);
  const [currentAdminPin, setCurrentAdminPin] = useState("");
  const [newAdminPin, setNewAdminPin] = useState("");
  const [confirmAdminPin, setConfirmAdminPin] = useState("");
  const [adminPinMsg, setAdminPinMsg] = useState(null);
  const fileRef = useRef(null);
  const restoreRef = useRef(null);

  const submitPinChange = () => {
    if (!newPin.trim() || newPin.trim().length < 4) {
      setPinMsg({ type: "error", text: "يجب أن يتكون الرمز الجديد من 4 أرقام/أحرف على الأقل." });
      return;
    }
    if (newPin.trim() !== confirmPin.trim()) {
      setPinMsg({ type: "error", text: "تأكيد الرمز الجديد غير مطابق." });
      return;
    }
    const ok = onChangePin(currentPin, newPin);
    if (!ok) {
      setPinMsg({ type: "error", text: "الرمز الحالي غير صحيح." });
      return;
    }
    setPinMsg({ type: "success", text: "تم تغيير رمز الدخول بنجاح. سيُطلب الرمز الجديد في المرة القادمة." });
    setCurrentPin("");
    setNewPin("");
    setConfirmPin("");
  };

  const submitAdminPinChange = () => {
    if (!newAdminPin.trim() || newAdminPin.trim().length < 4) {
      setAdminPinMsg({ type: "error", text: "يجب أن يتكون رمز المسؤول الجديد من 4 أرقام/أحرف على الأقل." });
      return;
    }
    if (newAdminPin.trim() !== confirmAdminPin.trim()) {
      setAdminPinMsg({ type: "error", text: "تأكيد رمز المسؤول الجديد غير مطابق." });
      return;
    }
    const ok = onChangeAdminPin(currentAdminPin, newAdminPin);
    if (!ok) {
      setAdminPinMsg({ type: "error", text: "رمز المسؤول الحالي غير صحيح." });
      return;
    }
    setAdminPinMsg({ type: "success", text: "تم تغيير رمز المسؤول بنجاح." });
    setCurrentAdminPin("");
    setNewAdminPin("");
    setConfirmAdminPin("");
  };

  const downloadTemplate = () => {
    const ws = XLSX.utils.aoa_to_sheet([
      ["الرقم الوظيفي", "رمز الباركود", "الاسم", "القسم", "الهاتف", "رابط الصورة"],
      ["1001", "1001", "أحمد محمد علي", "الأمن الإداري", "0500000000", ""],
      ["1002", "HE2599ATMS", "سالم عبدالله", "صيانة الكهرباء", "0500000001", "https://example.com/photo.jpg"],
    ]);
    ws["!cols"] = [{ wch: 14 }, { wch: 16 }, { wch: 26 }, { wch: 20 }, { wch: 16 }, { wch: 30 }];
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "قالب الموظفين");
    const out = XLSX.write(wb, { bookType: "xlsx", type: "array" });
    downloadBlob(out, "قالب_استيراد_الموظفين.xlsx", "application/octet-stream");
  };

  const readWorkbookRows = (file) =>
    new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onerror = () => reject(new Error("read-error"));
      reader.onload = (evt) => {
        try {
          const data = new Uint8Array(evt.target.result);
          const wb = XLSX.read(data, { type: "array" });
          const sheet = wb.Sheets[wb.SheetNames[0]];
          resolve(XLSX.utils.sheet_to_json(sheet, { defval: "" }));
        } catch (err) {
          reject(err);
        }
      };
      reader.readAsArrayBuffer(file);
    });

  const handleFile = async (file) => {
    setImporting(true);
    setImportMsg(null);
    try {
      const rows = await readWorkbookRows(file);

      if (rows.length === 0) {
        setImportMsg({ type: "error", text: "الملف لا يحتوي على أي صفوف بيانات تحت صف العناوين." });
        return;
      }

      const result = await onBulkImport(rows);

      if (result.headerIssue) {
        const foundHeaders = Object.keys(rows[0]).join("، ");
        setImportMsg({
          type: "error",
          text: `لم يتمكن النظام من التعرف على عمودي "الرقم الوظيفي" و"الاسم" في الملف. الأعمدة الموجودة في الملف هي: ${foundHeaders}. يرجى تسمية الأعمدة بالضبط كما في القالب.`,
        });
        return;
      }

      if (result.added === 0 && result.updated === 0) {
        setImportMsg({
          type: "error",
          text: `لم تتم إضافة أو تحديث أي عامل من أصل ${result.total} صف. تأكد أن حقل الرقم الوظيفي/الاسم غير فارغ في الصفوف.`,
        });
        return;
      }

      const photoNote =
        result.photosFetched || result.photosFailed
          ? ` تم تحميل ${result.photosFetched} صورة${result.photosFailed ? `، وتعذّر تحميل ${result.photosFailed} صورة (تحقق من صلاحية الروابط أو إعدادات CORS للموقع المستضيف).` : "."}`
          : "";

      setImportMsg({
        type: "success",
        text: `تمت إضافة ${result.added} عامل جديد، وتحديث بيانات ${result.updated} عامل موجود مسبقاً، من أصل ${result.total} صف (تجاهل ${result.skipped} صف ناقص البيانات).${photoNote}`,
      });
    } catch (err) {
      setImportMsg({ type: "error", text: "تعذّرت قراءة الملف. تأكد من أنه بصيغة إكسيل صحيحة (xlsx أو xls أو csv)." });
    } finally {
      setImporting(false);
    }
  };

  const handleRestore = (file) => {
    const reader = new FileReader();
    reader.onload = (evt) => {
      try {
        const parsed = JSON.parse(evt.target.result);
        onRestoreAll(parsed);
        setImportMsg({ type: "success", text: "تم استرجاع النسخة الاحتياطية بنجاح." });
      } catch (err) {
        setImportMsg({ type: "error", text: "ملف النسخة الاحتياطية غير صالح." });
      }
    };
    reader.readAsText(file);
  };

  const exportFullBackup = () => {
    const payload = JSON.stringify({ employees, departments }, null, 2);
    downloadBlob(payload, `نسخة_احتياطية_${todayStr()}.json`, "application/json");
  };

  return (
    <div className="page">
      <div className="page-header">
        <div>
          <h1>النسخ الاحتياطي والاستيراد</h1>
          <p className="page-sub">استيراد دفعات كبيرة من الموظفين وحفظ نسخة احتياطية من بياناتك</p>
        </div>
      </div>

      <div className="backup-grid">
        <div className="card backup-card">
          <FileSpreadsheet size={22} />
          <h3>قالب استيراد جاهز</h3>
          <p>حمّل نموذج إكسيل مهيأ مسبقاً بالأعمدة الصحيحة، ثم عبّئه ببيانات العمال (يدعم أكثر من 600 عامل دفعة واحدة). الأعمدة "رمز الباركود" و"رابط الصورة" اختيارية.</p>
          <button className="btn btn-secondary" onClick={downloadTemplate}>
            <Download size={16} /> تنزيل القالب
          </button>
        </div>

        <div className="card backup-card">
          <Upload size={22} />
          <h3>استيراد / تحديث من إكسيل</h3>
          <p>ارفع الملف لإضافة موظفين جدد، وتحديث بيانات الموظفين الموجودين مسبقاً (بنفس الرقم الوظيفي) تلقائياً — بما في ذلك صورهم إن أضفت عمود "رابط الصورة". يمكنك إعادة رفع نفس الملف لاحقاً بعد أي تعديل لتحديث الجميع دفعة واحدة.</p>
          <input
            ref={fileRef}
            type="file"
            accept=".xlsx,.xls,.csv"
            className="hidden-file-input"
            onChange={(e) => { if (e.target.files[0]) handleFile(e.target.files[0]); e.target.value = ""; }}
          />
          <button className="btn btn-primary" onClick={() => fileRef.current?.click()} disabled={importing}>
            <Upload size={16} /> {importing ? "جاري الاستيراد..." : "اختيار ملف واستيراد"}
          </button>
        </div>

        <div className="card backup-card">
          <FileSpreadsheet size={22} />
          <h3>تصدير بيانات الموظفين</h3>
          <p>نزّل نسخة إكسيل كاملة من جميع الموظفين وحالاتهم الحالية.</p>
          <button className="btn btn-secondary" onClick={() => exportEmployeesToXlsx(employees, departments, `الموظفون_${todayStr()}.xlsx`)}>
            <Download size={16} /> تصدير كإكسيل
          </button>
        </div>

        <div className="card backup-card">
          <FileJson size={22} />
          <h3>نسخة احتياطية كاملة</h3>
          <p>احفظ نسخة كاملة (الموظفون + الأقسام) بصيغة JSON، أو استرجع نسخة سابقة.</p>
          <div className="backup-btn-row">
            <button className="btn btn-secondary" onClick={exportFullBackup}>
              <Download size={16} /> تنزيل نسخة
            </button>
            <input
              ref={restoreRef}
              type="file"
              accept=".json"
              className="hidden-file-input"
              onChange={(e) => { if (e.target.files[0]) handleRestore(e.target.files[0]); e.target.value = ""; }}
            />
            <button className="btn btn-secondary" onClick={() => restoreRef.current?.click()}>
              <Upload size={16} /> استرجاع نسخة
            </button>
          </div>
        </div>
      </div>

      {importMsg && (
        <div className={`import-msg ${importMsg.type}`} style={{ marginBottom: 18 }}>
          {importMsg.type === "success" ? <CheckCircle2 size={16} /> : <AlertTriangle size={16} />}
          {importMsg.text}
        </div>
      )}

      <div className="card pin-card">
        <div className="card-head">
          <h3><Lock size={15} style={{ verticalAlign: "-2px", marginLeft: 6 }} /> رمز حماية النظام</h3>
        </div>
        <p className="page-sub" style={{ marginBottom: 14 }}>
          يُطلب هذا الرمز من أي جهاز يفتح النظام. الرمز الافتراضي عند أول استخدام هو <b>{DEFAULT_PIN}</b> — يُفضّل تغييره الآن.
        </p>
        <div className="pin-form">
          <input className="input" type="password" placeholder="الرمز الحالي" value={currentPin} onChange={(e) => { setCurrentPin(e.target.value); setPinMsg(null); }} />
          <input className="input" type="password" placeholder="الرمز الجديد" value={newPin} onChange={(e) => { setNewPin(e.target.value); setPinMsg(null); }} />
          <input className="input" type="password" placeholder="تأكيد الرمز الجديد" value={confirmPin} onChange={(e) => { setConfirmPin(e.target.value); setPinMsg(null); }} />
          <button className="btn btn-primary" onClick={submitPinChange}>تغيير الرمز</button>
        </div>
        {pinMsg && (
          <div className={`import-msg ${pinMsg.type}`} style={{ marginTop: 12 }}>
            {pinMsg.type === "success" ? <CheckCircle2 size={16} /> : <AlertTriangle size={16} />}
            {pinMsg.text}
          </div>
        )}
      </div>

      <div className="card pin-card">
        <div className="card-head">
          <h3><ShieldCheck size={15} style={{ verticalAlign: "-2px", marginLeft: 6 }} /> رمز وضع المسؤول</h3>
        </div>
        <p className="page-sub" style={{ marginBottom: 14 }}>
          هذا رمز منفصل يُستخدم لتفعيل "وضع المسؤول" (الصلاحيات الكاملة) من داخل النظام. الرمز الافتراضي عند أول استخدام هو <b>{DEFAULT_ADMIN_PIN}</b> — يُفضّل تغييره الآن ومشاركته فقط مع المسؤولين.
        </p>
        <div className="pin-form">
          <input className="input" type="password" placeholder="رمز المسؤول الحالي" value={currentAdminPin} onChange={(e) => { setCurrentAdminPin(e.target.value); setAdminPinMsg(null); }} />
          <input className="input" type="password" placeholder="رمز المسؤول الجديد" value={newAdminPin} onChange={(e) => { setNewAdminPin(e.target.value); setAdminPinMsg(null); }} />
          <input className="input" type="password" placeholder="تأكيد رمز المسؤول الجديد" value={confirmAdminPin} onChange={(e) => { setConfirmAdminPin(e.target.value); setAdminPinMsg(null); }} />
          <button className="btn btn-primary" onClick={submitAdminPinChange}>تغيير الرمز</button>
        </div>
        {adminPinMsg && (
          <div className={`import-msg ${adminPinMsg.type}`} style={{ marginTop: 12 }}>
            {adminPinMsg.type === "success" ? <CheckCircle2 size={16} /> : <AlertTriangle size={16} />}
            {adminPinMsg.text}
          </div>
        )}
      </div>

      <div className="card branding-lock-card">
        <div className="branding-lock-icon">
          <img src={DEFAULT_LOGO_DATA_URL} alt={COMPANY_NAME} />
        </div>
        <div>
          <h3 style={{ margin: "0 0 4px", fontSize: 14 }}>الهوية البصرية مثبّتة</h3>
          <p className="page-sub" style={{ margin: 0 }}>
            شعار {COMPANY_NAME} الرسمي ثابت في خلفية النظام وشاشة الدخول، ولا يمكن تغييره من الإعدادات لضمان اتساق الهوية البصرية للشركة.
          </p>
        </div>
      </div>
    </div>
  );
}

/* ------------------------------------------------------------------ */
/* Main App                                                             */
/* ------------------------------------------------------------------ */

function applyDayRollover(data) {
  let emps = data.employees || [];
  let deps = data.departments || [];
  let mIds = data.mealIds || [];
  let mDate = data.mealDate || todayStr();
  let scans = data.recentScans || [];
  let archive = data.dailyArchive || {};
  if (mDate !== todayStr()) {
    if (mDate && (emps.length > 0 || mIds.length > 0)) {
      archive = { ...archive, [mDate]: buildDaySnapshot(emps, deps, mIds) };
      archive = pruneArchive(archive, DAILY_ARCHIVE_RETENTION_DAYS);
    }
    emps = emps.map((e) => ({ ...e, status: "absent", checkInTime: null, checkOutTime: null }));
    mIds = [];
    scans = [];
    mDate = todayStr();
  }
  return {
    employees: emps,
    departments: deps,
    mealIds: mIds,
    mealDate: mDate,
    recentScans: scans,
    accessPin: data.accessPin || DEFAULT_PIN,
    adminPin: data.adminPin || DEFAULT_ADMIN_PIN,
    dailyArchive: archive,
  };
}

export default function WorkforceApp() {
  const [loaded, setLoaded] = useState(false);
  const [unlocked, setUnlocked] = useState(false);
  const [accessPin, setAccessPin] = useState(DEFAULT_PIN);
  const [adminPin, setAdminPin] = useState(DEFAULT_ADMIN_PIN);
  const [role, setRole] = useState("operator");
  const [showAdminPrompt, setShowAdminPrompt] = useState(false);
  const [employees, setEmployees] = useState([]);
  const [departments, setDepartments] = useState([]);
  const [mealDate, setMealDate] = useState(todayStr());
  const [mealIds, setMealIds] = useState([]);
  const [dailyArchive, setDailyArchive] = useState({});
  const [view, setView] = useState("dashboard");
  const [mobileNavOpen, setMobileNavOpen] = useState(false);
  const [scanFeedback, setScanFeedback] = useState(null);
  const [recentScans, setRecentScans] = useState([]);
  const [syncing, setSyncing] = useState(false);
  const lastPayloadRef = useRef("");
  const beep = useBeep();
  const employeeLookup = useMemo(() => buildEmployeeLookup(employees), [employees]);

  const applyRemoteData = useCallback((data) => {
    const rolled = applyDayRollover(data);
    setEmployees(rolled.employees);
    setDepartments(rolled.departments);
    setMealIds(rolled.mealIds);
    setMealDate(rolled.mealDate);
    setRecentScans(rolled.recentScans);
    setAccessPin(rolled.accessPin);
    setAdminPin(rolled.adminPin);
    setDailyArchive(rolled.dailyArchive);
  }, []);

  // Load persisted data once (shared across every device/user opening this app)
  useEffect(() => {
    (async () => {
      try {
        const res = await window.storage.get(STORAGE_KEY, true);
        if (res && res.value) {
          applyRemoteData(JSON.parse(res.value));
          lastPayloadRef.current = res.value;
        } else {
          setDepartments([
            { id: uid(), name: "الأمن الإداري" },
            { id: uid(), name: "صيانة الكهرباء" },
          ]);
          setAccessPin(DEFAULT_PIN);
          setAdminPin(DEFAULT_ADMIN_PIN);
        }
      } catch (err) {
        setDepartments([
          { id: uid(), name: "الأمن الإداري" },
          { id: uid(), name: "صيانة الكهرباء" },
        ]);
        setAccessPin(DEFAULT_PIN);
        setAdminPin(DEFAULT_ADMIN_PIN);
      } finally {
        setLoaded(true);
      }
    })();
  }, [applyRemoteData]);

  // Persist on change (debounced lightly), shared so every device sees the same data
  useEffect(() => {
    if (!loaded) return;
    const payload = JSON.stringify({ employees, departments, mealIds, mealDate, recentScans, accessPin, adminPin, dailyArchive });
    const t = setTimeout(() => {
      lastPayloadRef.current = payload;
      window.storage.set(STORAGE_KEY, payload, true).catch(() => {});
    }, 250);
    return () => clearTimeout(t);
  }, [employees, departments, mealIds, mealDate, recentScans, accessPin, adminPin, dailyArchive, loaded]);

  // Pull remote changes made from other devices
  const syncFromRemote = useCallback(async () => {
    if (!loaded) return;
    setSyncing(true);
    try {
      const res = await window.storage.get(STORAGE_KEY, true);
      if (res && res.value && res.value !== lastPayloadRef.current) {
        applyRemoteData(JSON.parse(res.value));
        lastPayloadRef.current = res.value;
      }
    } catch (err) {
      // ignore transient sync errors
    } finally {
      setSyncing(false);
    }
  }, [loaded, applyRemoteData]);

  useEffect(() => {
    if (!loaded) return;
    const interval = setInterval(syncFromRemote, 12000);
    return () => clearInterval(interval);
  }, [loaded, syncFromRemote]);

  /* ---------------- Employees ---------------- */
  const addEmployee = useCallback((emp) => setEmployees((prev) => [...prev, emp]), []);
  const editEmployee = useCallback((emp) => {
    setEmployees((prev) => prev.map((e) => (e.id === emp.id ? emp : e)));
    if (emp.status !== "present") {
      setMealIds((prev) => prev.filter((m) => m.empId !== emp.id));
    }
  }, []);
  const deleteEmployee = useCallback((id) => {
    setEmployees((prev) => prev.filter((e) => e.id !== id));
    setMealIds((prev) => prev.filter((m) => m.empId !== id));
  }, []);

  /* ---------------- Departments ---------------- */
  const addDepartment = useCallback((dep) => setDepartments((prev) => [...prev, dep]), []);
  const editDepartment = useCallback(
    (dep) => setDepartments((prev) => prev.map((d) => (d.id === dep.id ? dep : d))),
    []
  );
  const deleteDepartment = useCallback((id) => setDepartments((prev) => prev.filter((d) => d.id !== id)), []);

  /* ---------------- Explicit check-in ---------------- */
  const checkInByCode = useCallback(
    (code) => {
      const value = code.trim();
      if (!value) return;
      const emp = findEmployeeByCode(employeeLookup, value);
      if (!emp) {
        beep("error");
        setScanFeedback({ type: "error", op: "in", message: `لا يوجد عامل بالرمز "${value}"`, code: value });
        return;
      }
      beep("success");
      const time = nowTimeStr();
      const alreadyPresent = emp.status === "present";
      const deptName = departments.find((d) => d.id === emp.deptId)?.name || "—";

      setEmployees((prev) =>
        prev.map((e) => (e.id === emp.id ? { ...e, status: "present", checkInTime: alreadyPresent ? e.checkInTime : time, checkOutTime: null } : e))
      );

      const alreadyInMeals = mealIds.some((m) => m.empId === emp.id);
      if (!alreadyInMeals) {
        setMealIds((prev) => (prev.some((m) => m.empId === emp.id) ? prev : [...prev, { empId: emp.id, time }]));
      }

      if (!alreadyPresent) {
        setRecentScans((prev) => [
          { id: emp.id, empNo: emp.empNo, name: emp.name, photo: emp.photo || "", deptName, type: "in", time },
          ...prev,
        ].slice(0, 2000));
      }

      setScanFeedback({
        type: "success",
        op: "in",
        photo: emp.photo || "",
        name: emp.name,
        empNo: emp.empNo,
        deptName,
        time,
        message: alreadyPresent
          ? `مسجّل حضوره مسبقاً اليوم`
          : alreadyInMeals
          ? `تم تسجيل الحضور الساعة ${time}`
          : `تم تسجيل الحضور وإضافته لقائمة الطعام`,
      });
    },
    [employeeLookup, departments, mealIds, beep]
  );

  /* ---------------- Explicit check-out ---------------- */
  const checkOutByCode = useCallback(
    (code) => {
      const value = code.trim();
      if (!value) return;
      const emp = findEmployeeByCode(employeeLookup, value);
      if (!emp) {
        beep("error");
        setScanFeedback({ type: "error", op: "out", message: `لا يوجد عامل بالرمز "${value}"`, code: value });
        return;
      }
      beep("success");
      const time = nowTimeStr();
      const alreadyOut = emp.status !== "present";
      const wasInMeals = mealIds.some((m) => m.empId === emp.id);
      const deptName = departments.find((d) => d.id === emp.deptId)?.name || "—";

      if (!alreadyOut) {
        setEmployees((prev) =>
          prev.map((e) => (e.id === emp.id ? { ...e, status: "absent", checkInTime: null, checkOutTime: time } : e))
        );
        setMealIds((prev) => prev.filter((m) => m.empId !== emp.id));
        setRecentScans((prev) => [
          { id: emp.id, empNo: emp.empNo, name: emp.name, photo: emp.photo || "", deptName, type: "out", time },
          ...prev,
        ].slice(0, 2000));
      }

      setScanFeedback({
        type: "success",
        op: "out",
        photo: emp.photo || "",
        name: emp.name,
        empNo: emp.empNo,
        deptName,
        time,
        message: alreadyOut
          ? `مسجّل خروجه مسبقاً (أو لم يسجّل حضوره اليوم)`
          : wasInMeals
          ? `تم تسجيل الخروج وإلغاء اسمه من قائمة الطعام`
          : `تم تسجيل الخروج`,
      });
    },
    [employeeLookup, departments, mealIds, beep]
  );

  /* ---------------- Manual check-in / check-out (from Employees page) ---------------- */
  const checkoutEmployee = useCallback((id) => {
    const time = nowTimeStr();
    setEmployees((prev) =>
      prev.map((e) => (e.id === id ? { ...e, status: "absent", checkInTime: null, checkOutTime: time } : e))
    );
    setMealIds((prev) => prev.filter((m) => m.empId !== id));
  }, []);

  const checkinEmployee = useCallback((id) => {
    const time = nowTimeStr();
    setEmployees((prev) =>
      prev.map((e) => (e.id === id ? { ...e, status: "present", checkInTime: time, checkOutTime: null } : e))
    );
    setMealIds((prev) => (prev.some((m) => m.empId === id) ? prev : [...prev, { empId: id, time }]));
  }, []);

  /* ---------------- Meals ---------------- */
  const addMeal = useCallback((entry) => setMealIds((prev) => (prev.some((m) => m.empId === entry.empId) ? prev : [...prev, entry])), []);
  const removeMeal = useCallback((empId) => setMealIds((prev) => prev.filter((m) => m.empId !== empId)), []);

  /* ---------------- Bulk import ---------------- */
  const bulkImport = useCallback(
    async (rows) => {
      let added = 0;
      let updated = 0;
      let skipped = 0;
      let bothMissing = 0;
      let photosFetched = 0;
      let photosFailed = 0;

      const newDepartments = [...departments];
      const byEmpNo = new Map(employees.map((e) => [e.empNo, { ...e }]));
      const newEmployees = [];

      const resolveDept = (deptRaw) => {
        if (!deptRaw) return "";
        const found = newDepartments.find((d) => d.name.trim() === deptRaw);
        if (found) return found.id;
        const created = { id: uid(), name: deptRaw };
        newDepartments.push(created);
        return created.id;
      };

      for (const row of rows) {
        const empNo = String(findField(row, EMP_NO_ALIASES)).trim();
        const barcode = String(findField(row, BARCODE_ALIASES)).trim();
        const name = String(findField(row, NAME_ALIASES)).trim();
        const deptRaw = String(findField(row, DEPT_ALIASES)).trim();
        const phone = String(findField(row, PHONE_ALIASES)).trim();
        const photoUrl = String(findField(row, PHOTO_URL_ALIASES)).trim();

        if (!empNo && !name) bothMissing++;
        if (!empNo || !name) {
          skipped++;
          continue;
        }

        let photoDataUrl = "";
        if (photoUrl) {
          try {
            photoDataUrl = await fetchImageAsDataUrl(photoUrl);
            photosFetched++;
          } catch (err) {
            photosFailed++;
          }
        }

        const existing = byEmpNo.get(empNo);
        if (existing) {
          existing.name = name || existing.name;
          if (deptRaw) existing.deptId = resolveDept(deptRaw);
          if (phone) existing.phone = phone;
          if (barcode) existing.barcode = barcode;
          if (photoDataUrl) existing.photo = photoDataUrl;
          byEmpNo.set(empNo, existing);
          updated++;
        } else {
          const deptId = resolveDept(deptRaw);
          const created = {
            id: uid(),
            empNo,
            barcode,
            name,
            deptId,
            phone,
            status: "absent",
            checkInTime: null,
            checkOutTime: null,
            photo: photoDataUrl,
          };
          byEmpNo.set(empNo, created);
          newEmployees.push(created);
          added++;
        }
      }

      setDepartments(newDepartments);
      setEmployees((prev) => {
        const updatedList = prev.map((e) => byEmpNo.get(e.empNo) || e);
        return [...updatedList, ...newEmployees];
      });

      const headerIssue = rows.length > 0 && bothMissing === rows.length;
      return { added, updated, skipped, total: rows.length, headerIssue, photosFetched, photosFailed };
    },
    [departments, employees]
  );

  const restoreAll = useCallback((data) => {
    if (Array.isArray(data.employees)) setEmployees(data.employees);
    if (Array.isArray(data.departments)) setDepartments(data.departments);
  }, []);

  const changePin = useCallback(
    (currentPin, newPin) => {
      if (currentPin.trim() !== accessPin) return false;
      setAccessPin(newPin.trim());
      return true;
    },
    [accessPin]
  );

  const changeAdminPin = useCallback(
    (currentPin, newPin) => {
      if (currentPin.trim() !== adminPin) return false;
      setAdminPin(newPin.trim());
      return true;
    },
    [adminPin]
  );

  const tryElevateToAdmin = useCallback(
    (pin) => {
      if (pin.trim() !== adminPin) return false;
      setRole("admin");
      setShowAdminPrompt(false);
      return true;
    },
    [adminPin]
  );

  const downgradeToOperator = useCallback(() => {
    setRole("operator");
    setView((v) => (v === "employees" || v === "departments" || v === "backup" ? "dashboard" : v));
  }, []);

  const companyStats = {
    present: employees.filter((e) => e.status === "present").length,
    absent: employees.filter((e) => e.status !== "present").length,
  };

  useEffect(() => {
    if (!scanFeedback) return;
    const t = setTimeout(() => setScanFeedback(null), 4000);
    return () => clearTimeout(t);
  }, [scanFeedback]);

  return (
    <div dir="rtl" lang="ar" className="app-root">
      <GlobalStyles />
      <Watermark />
      {!loaded ? (
        <div className="loading-screen">جاري تحميل البيانات...</div>
      ) : !unlocked ? (
        <LockScreen correctPin={accessPin} onUnlock={() => setUnlocked(true)} />
      ) : (
        <>
          <Sidebar
            current={view}
            onNavigate={setView}
            mobileOpen={mobileNavOpen}
            onCloseMobile={() => setMobileNavOpen(false)}
            companyStats={companyStats}
            onLock={() => { setUnlocked(false); setRole("operator"); }}
            role={role}
            onRequestAdmin={() => setShowAdminPrompt(true)}
            onDowngrade={downgradeToOperator}
          />
          <div className="main-area">
            <div className="topbar">
              <button className="icon-btn mobile-only" onClick={() => setMobileNavOpen(true)}>
                <Menu size={20} />
              </button>
              <div className="topbar-title">{NAV_ITEMS.find((n) => n.key === view)?.label}</div>
              <button className="sync-btn" onClick={syncFromRemote} title="مزامنة البيانات من الأجهزة الأخرى">
                <RefreshCw size={14} className={syncing ? "spin" : ""} /> مزامنة
              </button>
            </div>
            <div className="content">
              {view === "dashboard" && (
                <DashboardPage
                  employees={employees}
                  departments={departments}
                  onCheckIn={checkInByCode}
                  onCheckOut={checkOutByCode}
                  scanFeedback={scanFeedback}
                  recentScans={recentScans}
                  dailyArchive={dailyArchive}
                  todayDate={mealDate}
                />
              )}
              {view === "employees" && (
                role === "admin" ? (
                  <EmployeesPage
                    employees={employees}
                    departments={departments}
                    onAdd={addEmployee}
                    onEdit={editEmployee}
                    onDelete={deleteEmployee}
                    onCheckout={checkoutEmployee}
                    onCheckin={checkinEmployee}
                  />
                ) : (
                  <UnauthorizedPage onRequestAdmin={() => setShowAdminPrompt(true)} />
                )
              )}
              {view === "departments" && (
                role === "admin" ? (
                  <DepartmentsPage
                    employees={employees}
                    departments={departments}
                    onAdd={addDepartment}
                    onEdit={editDepartment}
                    onDelete={deleteDepartment}
                  />
                ) : (
                  <UnauthorizedPage onRequestAdmin={() => setShowAdminPrompt(true)} />
                )
              )}
              {view === "meals" && (
                <MealsPage
                  employees={employees}
                  departments={departments}
                  mealIds={mealIds}
                  onAddMeal={addMeal}
                  onRemoveMeal={removeMeal}
                  dailyArchive={dailyArchive}
                  todayDate={mealDate}
                  canEdit={role === "admin"}
                />
              )}
              {view === "backup" && (
                role === "admin" ? (
                  <BackupPage
                    employees={employees}
                    departments={departments}
                    onBulkImport={bulkImport}
                    onRestoreAll={restoreAll}
                    onChangePin={changePin}
                    onChangeAdminPin={changeAdminPin}
                  />
                ) : (
                  <UnauthorizedPage onRequestAdmin={() => setShowAdminPrompt(true)} />
                )
              )}
            </div>
          </div>
          {showAdminPrompt && (
            <AdminPinModal onSubmit={tryElevateToAdmin} onClose={() => setShowAdminPrompt(false)} />
          )}
        </>
      )}
    </div>
  );
}

